import{_ as r,l as i,o,c as l,v as e,p as d,x as t,d as n,i as D,S as T}from"./chunks/framework.InCnrqk-.js";const H=JSON.parse('{"title":"DoH / DoT","description":"","frontmatter":{"title":"DoH / DoT","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/doh-dot.md","filePath":"cs/doh-dot.md","lastUpdated":1789023840000}'),p={name:"cs/doh-dot.md"};function h(c,a,S,_,u,E){const s=i("Mermaid");return o(),l("div",null,[a[1]||(a[1]=e('<h1 id="doh-dot" tabindex="-1">DoH / DoT <a class="header-anchor" href="#doh-dot" aria-label="Permalink to &quot;DoH / DoT&quot;">​</a></h1><div class="epigraph"><p>DoT 在 TLS 上跑 DNS 报文，DoH 把查询放进 HTTPS；机密对路径上的观察者隐藏 QNAME，把信任挪到解析器运营方。</p><footer>—— 据 RFC 7858 DoT；RFC 8484 DoH 整理</footer></div><p><a href="/cs/dnssec">DNSSEC</a> 不加密。<a href="/cs/http-tls-entry">TLS 入口</a> 已有信道。<a href="/cs/dnssec">上一课</a> 留下嗅探。缺口是 <strong>DoT/DoH</strong>：端口 853 vs 443、与企业过滤的张力。本课不把 GeoDNS 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>咖啡馆 Wi‑Fi 看见你查询。DoT：TCP/TLS 853。DoH：GET/POST <code>application/dns-message</code>，混在 Web 流量里。客户端要钉解析器证书（或系统配置），否则只是换中间人。DNSSEC 仍可在隧道里验数据。与 QUIC：DoQ 点名。Cookie 与 DoH 共享 HTTPS 栈，缓存层次不同。</p><p>不要把 DoH 写成 DNSSEC 的替代。</p><p><span class="marginnote">RFC 8484。Split DNS 企业场景会冲突。本课不站队政策。</span></p><h3 id="机密化-stub–递归" tabindex="-1">机密化 stub–递归 <a class="header-anchor" href="#机密化-stub–递归" aria-label="Permalink to &quot;机密化 stub–递归&quot;">​</a></h3><p>信任挪到解析器运营方。DNSSEC 仍验数据。企业过滤与 443 混叠是政策张力。不是 DNSSEC 替代。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：53 明文 / DoT / DoH。画：stub → TLS → 解析器。与 Happy Eyeballs 同类：发现与回退。</p>',11)),(o(),d(T,null,{default:t(()=>[D(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20STUB%5B%22%E5%AD%98%E6%A0%B9%22%5D%20--%3E%20DOT%5B%22TLS%20853%22%5D%0A%20%20STUB%20--%3E%20DOH%5B%22HTTPS%20443%22%5D%0A%20%20AUTH%5B%22%E4%BB%8D%E9%97%AE%E6%9D%83%E5%A8%81%2053%20%E6%88%96%E5%90%8C%E6%A0%B7%E5%8A%A0%E5%AF%86%22%5D%20--%3E%20REC%5B%22%E9%80%92%E5%BD%92%E5%99%A8%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>递归器到权威仍常明文，观察点上移到大型解析器。TTL 缓存仍在递归器。H3 可载 DoH。中间企业防火墙看见 443 无法按域过滤 DNS，这是设计后果。RTT：多一次 TLS，连接复用摊销，像 HTTP 持久。</p><p>SYN 泛洪变成 HTTPS 泛洪，对象换层。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 Oblivious DoH 的全部。GeoDNS 是下一课。后课默认：DoT/DoH 机密化 stub–递归；信任解析器。</p><p>把所有设备钉同一公共 DoH，等于把元数据集中。</p><p>上一课留下的缺口在本课收口；「DoH / DoT」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/geodns">GeoDNS</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DoT/DoH 加密查询路径。</li><li>DNSSEC 仍验数据。</li><li>信任与可见性从路径挪到解析器。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 7858；RFC 8484。</li></ul>',10))])}const b=r(p,[["render",h]]);export{H as __pageData,b as default};
